<script setup lang="ts">
import { computed, ref, watch } from 'vue';
import { route as routeSource,go,setQuery,back } from '../workbench/navigation';
import { findAuditActivity, findAuditStep, evidenceOrigin, requirementIn, executionNames, reviewNames, type Review, type AuditRef } from '../workbench/activity-review-mock';
import { defaultAspectNames } from '../workbench/evaluation-mock';
import { downloadTrace } from '../workbench/traces';
import WaterfallChart from './WaterfallChart.vue';
import SemanticTimeline from './SemanticTimeline.vue';
import ActivityStepDetail from './ActivityStepDetail.vue';
import WorkbenchDialog from './WorkbenchDialog.vue';
const route=routeSource,location=window.location;
const context=computed(()=>findAuditActivity(route.id));
const audit=computed(()=>context.value?.audit);
const round=computed(()=>audit.value?.rounds.find(r=>r.id===route.round)||(route.round?undefined:audit.value?.rounds[0]));
const chosen=computed(()=>round.value?(route.span?findAuditStep(round.value.steps,route.span):round.value.steps.find(s=>s.status==='failed')||round.value.steps[0]):undefined);
const tabs={process:'交互过程',evaluation:'评价结果',definitions:'采用定义',handling:'审查记录'};
const tab=computed(()=>Object.keys(tabs).includes(route.tab)?route.tab:'process');
const chapter=computed(()=>audit.value?.snapshot.book.units.flatMap(u=>u.chapters).find(ch=>ch.id===context.value?.activity.chapterId));
const claim=computed(()=>audit.value?.snapshot.claims.find(c=>c.id===audit.value?.claimId));
const aspect=(id:string)=>(defaultAspectNames as Record<string,string>)[id]||id;
const methodName=(id:string)=>audit.value?.snapshot.domain.methods.find(m=>m.id===id)?.name||id;
const totalDuration=computed(()=>audit.value?.rounds.reduce((sum,r)=>sum+r.duration,0)||0);
const roundEvidence=computed(()=>context.value?.activity.evidence.filter(e=>round.value?.evidenceIds.includes(e.id))||[]);
const references=computed<AuditRef[]>(()=>audit.value&&context.value?[{kind:'chapter',id:context.value.activity.chapterId},{kind:'target',id:audit.value.snapshot.target.id},{kind:'task',id:audit.value.taskId},...audit.value.methodIds.map(id=>({kind:'solution' as const,id})),{kind:'claim',id:audit.value.claimId},...audit.value.requirementIds.map(id=>({kind:'requirement' as const,id}))]:[]);
const refNames={chapter:'教材章节',target:'学习目标',task:'Task',solution:'Solution',claim:'Task Claim',requirement:'学习要求',evidence:'Evidence',observation:'Observation'};
function refName(r:AuditRef){const b=audit.value?.snapshot;if(!b)return r.id;return r.kind==='chapter'?chapter.value?.name||r.id:r.kind==='target'?b.target.name:r.kind==='claim'?b.claims.find(c=>c.id===r.id)?.name||r.id:r.kind==='task'?b.domain.tasks.find(t=>t.id===r.id)?.name||r.id:r.kind==='solution'?methodName(r.id):r.kind==='requirement'?requirementIn(audit.value!,r.id)?.name||r.id:r.id;}
function version(r:AuditRef){const b=audit.value!.snapshot;return r.kind==='claim'?'v'+b.claims.find(c=>c.id===r.id)?.version:r.kind==='chapter'?'教材 v'+b.book.revision:r.kind==='target'||r.kind==='requirement'?'目标 v'+b.target.revision:'当时采用快照';}
const reference=ref<AuditRef|null>(null);
const refEvidence=computed(()=>context.value&&reference.value?.kind==='evidence'?evidenceOrigin(context.value.space.id,reference.value.id):undefined);
const refObservation=computed(()=>reference.value?.kind==='observation'?audit.value?.rounds.find(r=>r.observation?.id===reference.value!.id)?.observation:undefined);
const referenceFields=computed(()=>{
  const r=reference.value,b=audit.value?.snapshot;if(!r||!b)return [];
  if(r.kind==='claim'){const c=b.claims.find(c=>c.id===r.id);return c?[['任务',b.domain.tasks.find(t=>t.id===c.taskId)?.name||c.taskId],['方法条件',(c.methodMode==='all'?'要求分别覆盖：':'任选一种：')+c.methods.map(methodName).join('、')],['实际帮助边界',c.support],['评价方面',c.aspects.map(a=>a.name+'：'+(a.applicable?a.criterion:'不适用；'+a.reason)).join('\n')]]:[];}
  if(r.kind==='target')return [['目标说明',b.target.description],['本活动涉及的要求',audit.value!.requirementIds.map(id=>requirementIn(audit.value!,id)?.name||id).join('\n')],['适用边界','本活动仅涉及所列要求，不把整个目标的其他章节纳入本次处理。']];
  if(r.kind==='requirement'){const requirement=requirementIn(audit.value!,r.id);return requirement?[['要求名称',requirement.name],['所属章节',requirement.chapterIds.map(id=>b.book.units.flatMap(u=>u.chapters).find(ch=>ch.id===id)?.name||id).join('、')],['采用方面',requirement.aspectIds.map(aspect).join('、')],['达标标准',requirement.standard]]:[];}
  if(r.kind==='task'){const t=b.domain.tasks.find(t=>t.id===r.id);return t?[['任务目标',t.goal],['完成责任',t.responsibility],['预期输出',t.output],['本次实际采用方法',audit.value!.methodIds.map(methodName).join('、')],['适用边界',t.exclusions]]:[];}
  if(r.kind==='solution'){const m=b.domain.methods.find(m=>m.id===r.id);return m?[['方法说明',m.description],['适用条件',m.conditions],['步骤',m.steps.map(s=>s.title+'：'+s.detail+(s.solutionId?'（子方法：'+methodName(s.solutionId)+'）':'')).join('\n')],['直接关联 KC',m.kc.map(id=>b.domain.knowledge.find(k=>k.id===id)?.name||id).join('、')]]:[];}
  if(r.kind==='chapter')return [['教材',b.book.name],['章节',chapter.value?.name||r.id],['内容',chapter.value?.content||'未记录'],['当前活动',context.value!.activity.name]];
  if(r.kind==='observation'){const o=refObservation.value;return o?[['内容',o.text],['实际帮助',o.support],['来源输入',context.value!.activity.messages[o.messageIndex]?.text||'未记录'],['提交边界','通过校验后提交的观察；候选被拒绝不产生此记录。']]:[];}
  const e=refEvidence.value;return e?[['源活动',e.activity.name+' · '+e.activity.at],['Task Claim',b.claims.find(c=>c.id===e.evidence.claimId)?.name||e.evidence.claimId],['评价方面',aspect(e.evidence.aspectId)],['证据解释',e.evidence.meaning],['源活动帮助',e.activity.help]]:[];
});
function openCurrent(){const r=reference.value,b=audit.value?.snapshot;if(!r||!b)return;const returnTo=location.hash;reference.value=null;
  if(r.kind==='chapter')go('textbooks',{id:b.book.id,chapter:r.id,tab:'mapping',returnTo});
  else if(r.kind==='target'||r.kind==='requirement')go('targets',{id:b.target.id,claim:r.kind==='requirement'?audit.value!.claimId:'',returnTo});
  else if(r.kind==='claim')go('evaluation',{id:r.id,tab:'definition',returnTo});
  else go('domain',{domain:b.book.domainId,filter:r.kind,id:r.id,returnTo});
}
function openEvidenceOrigin(){const source=refEvidence.value;if(!source)return;const from=findAuditActivity(source.activity.id)?.audit;const r=from?.rounds.find(r=>r.evidenceIds.includes(source.evidence.id));reference.value=null;if(source.activity.id===route.id)setQuery({tab:'process',round:r?.id||'',span:r?.id+'-evidence'});else go('activity',{id:source.activity.id,round:r?.id,span:r?.id+'-evidence',returnTo:location.hash});}
function selectRound(id:string){setQuery({round:id,span:''});}
function exportActivity(){if(!context.value)return;downloadTrace(context.value.activity.id+'-review.json',{source:'authored-current-course-mock',notice:'人工编写的过程与时间示例，不是采集日志；不会运行模型或更新个人判断。',space:{id:context.value.space.id,studentId:context.value.space.studentId},activity:context.value.activity,audit:audit.value});}
const draftReview=ref<Review>('unreviewed'),note=ref(''),error=ref(''),saved=ref('');
watch(()=>route.id,()=>{reference.value=null;draftReview.value=audit.value?.review||'unreviewed';note.value='';error.value='';saved.value='';},{immediate:true});
function saveReview(){if(!audit.value)return;if(!note.value.trim()){error.value='请填写复核结论及依据。';return;}audit.value.review=draftReview.value;audit.value.reviewNotes.unshift({at:new Date().toLocaleString('sv-SE',{hour12:false}),review:draftReview.value,text:note.value.trim()});note.value='';error.value='';saved.value='已保存本次 mock 审查记录；未修改执行记录、定义或个人判断。';}
</script>
<template><div class="wb-page activity-review-detail">
  <template v-if="context&&audit">
    <header class="page-header"><div><button class="text-link" @click="back('trace-list')">← {{route.returnTo.startsWith('#/dashboard')?'返回运行总览':route.returnTo.startsWith('#/students')?'返回学生状态':route.returnTo.startsWith('#/objects')?'返回空间观测':route.returnTo.startsWith('#/learning-spaces')?'返回学习空间':route.returnTo.startsWith('#/activity')?'返回来源活动':'返回交互审查'}}</button><h2>{{context.activity.name}}</h2><p class="page-desc"><button class="text-link" @click="go('students',{id:context.space.studentId,scope:context.space.id,returnTo:location.hash})">{{context.space.studentName}} ↗</button> · <button class="text-link" @click="go('learning-spaces',{id:context.space.id,tab:'records',returnTo:location.hash})">{{context.space.name}} ↗</button> · {{chapter?.name}} · {{context.activity.at}}</p><p class="muted">{{context.activity.id}} · {{audit.rounds.length}} 轮 · 预写处理过程，耗时与模型调用均为演示值</p></div><button class="btn" @click="exportActivity">导出本次示例 JSON</button></header>
    <div class="audit-summary"><div><span>执行状态</span><strong class="badge" :class="audit.execution==='completed'?'green':'amber'">{{executionNames[audit.execution]}}</strong><small>描述处理，不表示学习目标达标</small></div><div><span>审查情况</span><strong class="badge" :class="audit.review==='question'?'amber':''">{{reviewNames[audit.review]}}</strong><small>与执行状态分别记录</small></div><div><span>评价产物</span><strong>{{context.activity.evidence.length}} 条 Evidence</strong><small>按 Claim 各方面保留判断</small></div><div><span>示例处理耗时</span><strong>{{(totalDuration/1000).toFixed(2)}}s</strong><small>各轮处理相加，不含学生思考等待</small></div></div>
    <div class="tabs" role="tablist" aria-label="活动审查"><button v-for="(name,key) in tabs" :key="key" role="tab" :aria-selected="tab===key" :class="{active:tab===key}" @click="setQuery({tab:key})">{{name}}</button></div>
    <template v-if="tab==='process'||tab==='evaluation'">
      <nav class="round-list" aria-label="交互轮次"><button v-for="(r,i) in audit.rounds" :key="r.id" class="round-button" :aria-pressed="round?.id===r.id" :class="{selected:round?.id===r.id}" @click="selectRound(r.id)"><strong>第 {{i+1}} 轮 · {{r.name}}</strong><span>{{r.trigger}} · {{executionNames[r.execution]}} · {{r.evidenceIds.length}} 条 Evidence</span></button></nav>
      <template v-if="round">
        <template v-if="tab==='process'">
          <section class="panel round-dialogue"><div class="section-heading"><h3>本轮交互</h3><span class="muted">{{round.id}} · 帮助与作答按发生顺序保留</span></div><details v-if="round.contextIndices.length" class="prior-context"><summary>查看轮前题目与已发生的帮助</summary><div v-for="index in round.contextIndices" :key="index" class="message-context"><strong>{{context.activity.messages[index]?.actor}}</strong><p>{{context.activity.messages[index]?.text}}</p></div></details><article v-for="index in round.messageIndices" :key="index" class="dialogue-message" :class="{learner:context.activity.messages[index]?.actor==='学生'}"><strong>{{context.activity.messages[index]?.actor==='学生'?'学习者输入':'实际展示（示例）'}}</strong><p>{{context.activity.messages[index]?.text}}</p></article><p class="help-context">帮助条件：{{round.help}}</p><p v-if="!round.messageIndices.some(i=>context!.activity.messages[i]?.actor==='DeerMind')" class="muted">本轮没有已记录的系统回复；下方处理结果不冒充学生已看到的内容。</p></section>
          <div class="audit-process-grid"><section class="waterfall-section"><h3 class="pane-title">本轮处理链 · 瀑布图</h3><WaterfallChart :spans="round.steps" :total-duration="round.duration" :selected-span-id="chosen?.spanId||null" @select="setQuery({span:$event})"/></section><section class="detail-section"><h3 class="pane-title">步骤详情</h3><ActivityStepDetail v-if="chosen" :key="chosen.spanId" :step="chosen" @reference="reference=$event"/><p v-else class="empty">该步骤不属于本轮。请在左侧选择步骤。</p></section></div>
          <details class="timeline-disclosure"><summary>查看本轮语义对象时间线</summary><SemanticTimeline :events="round.events" @select-span="setQuery({span:$event})"/></details><details class="full-dialogue"><summary>查看本活动完整对话</summary><div v-for="(m,i) in context.activity.messages" :key="i" class="dialogue-message"><strong>{{i+1}} · {{m.actor}}</strong><p>{{m.text}}</p></div></details>
        </template>
        <template v-else>
          <section class="panel"><div class="section-heading"><h3>本轮 Evidence</h3><button class="text-link" @click="reference={kind:'claim',id:audit.claimId}">{{claim?.name}} · 采用 v{{claim?.version}} →</button></div><table v-if="roundEvidence.length" class="data-table round-evidence"><thead><tr><th>Evidence / 方面</th><th>表现解释</th><th>来源</th></tr></thead><tbody><tr v-for="e in roundEvidence" :key="e.id"><td><button class="text-link" @click="reference={kind:'evidence',id:e.id}">{{e.id}}</button><small>{{aspect(e.aspectId)}}</small></td><td>{{e.meaning}}</td><td><button class="text-link" @click="reference={kind:'observation',id:round.observation!.id}">{{round.observation?.id}} →</button></td></tr></tbody></table><p v-else class="empty">本轮仅处理求助，尚无个人作答 Evidence。正常讲解不要求每轮都更新能力判断。</p></section>
          <section v-if="round.changes.length" class="table-card"><h3>本轮前后 Belief · {{claim?.name}}</h3><table class="data-table round-beliefs"><thead><tr><th>方面</th><th>之前</th><th>之后</th><th>依据与适用边界</th></tr></thead><tbody><tr v-for="c in round.changes" :key="c.aspect"><td>{{aspect(c.aspect)}}</td><td>{{c.before}}</td><td>{{c.after}}</td><td>{{c.reason}}<button v-for="id in c.evidenceIds" :key="id" class="text-link reference-link" @click="reference={kind:'evidence',id}">{{id}} →</button></td></tr></tbody></table><p class="table-note">此处保留活动当时的前后判断，不用当前最新状态回填历史；不生成个人 KC 掌握率。</p></section>
          <section v-if="round.results.length" class="table-card"><h3>目标要求的本轮结果</h3><table class="data-table round-results"><thead><tr><th>具体学习要求</th><th>之前 → 之后</th><th>判断说明</th></tr></thead><tbody><tr v-for="r in round.results" :key="r.id"><td><button class="text-link" @click="reference={kind:'requirement',id:r.id}">{{requirementIn(audit,r.id)?.name||r.id}} →</button></td><td>{{r.before}} → {{r.after}}</td><td>{{r.reason}}</td></tr></tbody></table></section>
        </template>
      </template><section v-else class="panel"><h3>未找到该轮次</h3><p>不能用其他轮次的步骤代替。请从上方选择本活动的一轮。</p></section>
    </template>
    <template v-else-if="tab==='definitions'"><p class="muted">仅列本活动实际涉及的章节、Task、方法、Claim 和目标要求。先查看当时采用内容，再按需进入管理页面查看当前定义。</p><section class="table-card"><table class="data-table audit-definitions"><thead><tr><th>对象</th><th>类型</th><th>活动当时采用</th><th></th></tr></thead><tbody><tr v-for="r in references" :key="r.kind+r.id"><td>{{refName(r)}}<small>{{r.id}}</small></td><td>{{refNames[r.kind]}}</td><td>{{version(r)}}</td><td><button class="text-link" :aria-label="'查看采用内容 '+r.id" @click="reference=r">查看采用内容</button></td></tr></tbody></table></section><p class="muted">Solution 内部子方法及 KC 依据可在方法快照中追查，不把空间全部章节和模型目录当成本次处理依赖。</p></template>
    <section v-else class="panel audit-notes"><h3>活动审查记录</h3><p class="muted">记录人工复核结论；保存不会重跑模型、改写历史输入或修改个人 Belief。</p><form @submit.prevent="saveReview"><label>审查结论<select v-model="draftReview"><option v-for="(name,key) in reviewNames" :key="key" :value="key">{{name}}</option></select></label><label>结论与依据<textarea v-model="note" rows="3" placeholder="说明核对了哪些轮次、步骤和依据，以及尚未解决的疑点"/></label><p v-if="error" role="alert" class="callout danger">{{error}}</p><button class="btn primary" type="submit">保存审查记录</button><p v-if="saved" role="status">{{saved}}</p></form><div v-for="(n,i) in audit.reviewNotes" :key="i" class="review-note"><span class="badge" :class="n.review==='question'?'amber':''">{{reviewNames[n.review]}}</span><span class="muted">{{n.at}}</span><p>{{n.text}}</p></div><p v-if="!audit.reviewNotes.length" class="empty">尚无人工复核记录。</p></section>
    <WorkbenchDialog v-if="reference" :title="refNames[reference.kind]+' · '+refName(reference)" wide @close="reference=null"><p class="muted">{{reference.id}} · {{reference.kind==='evidence'||reference.kind==='observation'?'活动记录示例':version(reference)}} · {{context.space.studentName}} / {{context.space.name}}</p><dl class="field-list reference-fields"><template v-for="(f,i) in referenceFields" :key="i"><dt>{{f[0]}}</dt><dd>{{f[1]}}</dd></template></dl><p v-if="!referenceFields.length" class="callout amber">该引用没有可解析的内容；不借用其他对象代替。</p><div class="dialog-footer"><button v-if="reference.kind==='evidence'&&refEvidence" class="btn" @click="openEvidenceOrigin">查看源活动的解释步骤 →</button><button v-else-if="reference.kind==='observation'&&refObservation" class="btn" @click="setQuery({tab:'process',round:audit.rounds.find(r=>r.observation?.id===reference!.id)?.id||'',span:audit.rounds.find(r=>r.observation?.id===reference!.id)?.id+'-commit'});reference=null">查看提交步骤 →</button><template v-else-if="referenceFields.length"><p class="muted">管理页面显示当前定义；修改不会覆盖本次活动的采用快照。</p><button class="btn" @click="openCurrent">查看当前定义 ↗</button></template></div></WorkbenchDialog>
  </template>
  <section v-else class="panel"><h2>未找到该活动的处理记录</h2><p>不会显示其他活动的处理链。请返回交互审查选择已记录的示例。</p><button class="btn" @click="back('trace-list')">返回交互审查</button></section>
</div></template>
<style scoped>
.activity-review-detail{max-width:1700px}.page-header h2{margin-top:10px;font-size:21px}.page-header .muted{margin-top:8px}.page-header>.btn{flex-shrink:0}.audit-summary{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));background:white;border:1px solid #e1e8ed;border-radius:9px;padding:18px;gap:18px}.audit-summary>div{display:flex;flex-direction:column;align-items:flex-start;gap:7px;font-size:13px}.audit-summary>div>span{font-size:12px;color:#6f8375}.audit-summary small{font-size:11px;color:#7c8b80}.round-list{display:flex;gap:12px;overflow-x:auto;margin:18px 0;padding-bottom:4px}.round-button{min-width:260px;max-width:360px;display:flex;flex-direction:column;gap:5px;text-align:left;padding:12px 16px;border:1px solid #dae5de;border-radius:8px;background:white;color:#46644f}.round-button strong{font-size:13px}.round-button span{font-size:11px;color:#7c8b80}.round-button.selected{border-color:#53836a;background:#eef6f0;box-shadow:inset 3px 0 #397153}.section-heading{display:flex;justify-content:space-between;gap:14px;align-items:center;margin-bottom:12px}.section-heading h3{margin:0}.round-dialogue{padding:16px 18px}.dialogue-message{border-left:3px solid #bbd3c3;padding:9px 14px;margin:10px 0;background:#f6f9f7;font-size:13px}.dialogue-message.learner{border-left-color:#508369;background:#edf5ef}.dialogue-message strong,.message-context strong{font-size:12px;color:#627a6b}.dialogue-message p{margin:4px 0}.help-context{font-size:12px;color:#617b6a}.prior-context{border-top:0;margin:0;padding:0}.message-context{font-size:13px;margin:10px 0;padding:10px 14px;background:#f7f8fa}.audit-process-grid{display:grid;grid-template-columns:minmax(0,1.08fr) minmax(0,1fr);border:1px solid #dce6df;border-radius:8px;background:white;overflow:hidden;min-height:450px}.waterfall-section,.detail-section{min-width:0}.waterfall-section{border-right:1px solid #e1e8ed}.pane-title{font-size:13px;margin:0;padding:12px 16px;background:#f2f6f3;color:#61786a}.detail-section{background:#fafcfb}.detail-section :deep(.audit-step-detail){max-height:580px;overflow-y:auto}.waterfall-section :deep(.waterfall-body){max-height:580px;overflow-y:auto}.waterfall-section :deep(.row-name),.waterfall-section :deep(.col-name){width:170px}.timeline-disclosure,.full-dialogue{margin:18px 0}.round-evidence th:first-child{width:22%}.round-evidence th:last-child{width:20%}.round-beliefs th:first-child{width:13%}.round-beliefs th:nth-child(2),.round-beliefs th:nth-child(3){width:22%}.round-results th:first-child{width:31%}.round-results th:nth-child(2){width:150px}.reference-link{display:block;margin-top:6px}.table-note{padding:12px 18px;color:#758679;font-size:12px}.audit-definitions th:first-child{width:44%}.audit-definitions th:last-child{width:135px}.audit-notes form{max-width:850px}.audit-notes select{max-width:250px}.review-note{margin-top:20px;padding-top:18px;border-top:1px solid #e1e8ed}.review-note>span{margin-right:12px}.review-note p{white-space:pre-wrap}.activity-review-detail small,.data-table small{display:block}.reference-fields dd{white-space:pre-wrap}.reference-fields dt{word-break:keep-all}@media(max-width:1200px){.audit-process-grid{grid-template-columns:1fr}.waterfall-section{border-right:0}.waterfall-section :deep(.waterfall-body){max-height:310px}.detail-section :deep(.audit-step-detail){max-height:480px}.audit-summary{grid-template-columns:repeat(2,minmax(0,1fr))}.page-header{flex-wrap:wrap}.section-heading{flex-wrap:wrap}}
</style>
